response_expressions_direct:
SetCookie(w, &http.Cookie{
			Name:     tokenCookieName,
			Value:    tok,
			Path:     "/",
			HttpOnly: true,
			Secure:   requestUsesHTTPS(r),
			SameSite: http.SameSiteLaxMode,
			// 永続セッション Cookie 化を避け、失効口を与える。起動毎 token と
			// 不一致になれば（Hub 再起動で token がローテートされた等）期限切れ後に
			// 再認証へ倒れる。MaxAge>0 なら Expires も併せて付与される。
			MaxAge: int(tokenCookieMaxAge / time.Second),
		})

writeJSON(w, map[string]any{
		"cwd":              s.hubCWD,
		"custom_providers": customProviderOptions(cfg.CustomProviders),
		"version":          s.version,
		"binary_sha256":    s.binGuard.StartSHA(),
		"binary_stale":     binaryStale,
		"web_src_hash":     s.webSrcHash,
		"web_dist_fresh":   s.webDistFresh,
		"active_sessions":  s.activeSessionCount(),
		"git_commit":       s.gitCommit,
		"build_time":       s.buildTime,
		"runtime_mode":     mode,
		"runtime_label":    runtimeLabel(mode),
		"ssh":              sshSession,
		"host_ip":          hostIP,
		"env_kind":         env.Kind,
		"env_label":        env.Label,
		"env_short":        env.Short,
		"env_color":        env.Color,
		"env_title":        env.Title,
		"env_host_label":   env.HostLabel,
		"userAvatar":       userAvatar,
		"userDisplayName":  userDisplayName,
		// plan_session-handoff-board_c5_handoff-md.md 内部 C2: 経路 1（残量が
		// 近いときの通知）の閾値。UI 側はこの値未満（usage_stat が既に broadcast
		// している RateLimit5hPct/7dPct 等から計算した残量）を見て、セッション
		// ごとに 1 回だけ通知を出す。
		"handoff_notify_remaining_percent": cfg.Handoff.NotifyRemainingPercentOrDefault(),
		// 同じ帯の 2 つ目のボタン（前任に引き継ぎメモを書かせる）の扱い:
		// ask（既定）= 人が押す / auto = 帯と同時に画面が 1 回だけ叩く / off = 出さない
		// （子 plan: docs/local/plan_derived-session-launch_c4_handoff-routes.md 内部 C2）。
		// 閾値判定は今までどおりブラウザ側が usage_stat から行うので、Hub 側に
		// 残量を見張る仕組みは増やさない。
		"handoff_note_on_threshold": cfg.Handoff.NoteOnThresholdOrDefault(),
		// 起動要求の共通 3 項目の候補値（子 plan:
		// docs/local/plan_derived-session-launch_c1_request-schema.md 内部 C5）。
		// effort_levels は写像がある provider だけがキーを持つ（無い provider は
		// キーごと出さない＝画面は欄を出さない）。execution_modes /
		// permission_presets は「この build で選べる値」。headless / bounded は
		// それぞれの C で解禁済みなので、今は 3 値とも返る。
		"effort_levels":      s.effortLevelsByProvider(),
		"execution_modes":    config.AvailableExecutionModes(),
		"permission_presets": config.AvailablePermissionPresets(),
		// headless の定義がある provider（内蔵 + config.yaml の custom_providers）。
		// 実行モードに headless を選べるのは全 provider だが、定義が無いものは起動時に
		// 400 になる。画面はこの一覧を見て、押す前に「この CLI には headless の定義が
		// 無い」を権限欄と同じ場所へ 1 行出す（子 plan 内部 C6）。**判定の正本は
		// あくまで起動時の解決**で、これはその写し。
		"headless_providers": s.headlessProvidersFromRegistry(cfg),
		// 画面から立てる子（origin: "ui"）の実効権限。provider → 段 → 実効フラグで、
		// 内側の "" は「段を選んでいない」＝ UI 起点の対話既定（段 1）。派生ダイアログは
		// これを spawn 確認ダイアログと同じ描画関数へ渡す。確認ダイアログは spawn 時に
		// WS で同じ表を受け取るが、派生ダイアログには対になる要求がまだ存在しない
		// （人がこれから作る）ので、候補値と同じく /api/info から先に配る。
		// **表示専用で、Hub はこれを読み返さない**（子 plan:
		// docs/local/plan_derived-session-launch_c3_derive-launch.md 内部 C2）。
		"child_permission_preview": childApprovalPreviewTiers(spawnChildRequest{Origin: launchOriginUI}, cfg),
		// 無人のときの空段の着地（orchestration.child_permission_default。未設定は full）。
		// headless は端末が無いので defaultChildPermissionTier がここへ倒れる。派生の
		// 開示は ExecutionMode 空の表の "" キー（attended）を見ていたため、起動段と
		// ずれた。クライアントは headless+空段のときこの値で表を引き直す。決め打ち
		// full にしない（config で bounded / attended にできる）。D-12 の既定そのものは変えない。
		"child_permission_default": cfg.Orchestration.ChildPermissionDefaultTier(),
		// 役割 → 「次回もこの段を使う」で覚えた段（user_prefs.spawn.role_permission）。
		// 派生ダイアログが役割を選んだ時点で段の select をこの値にし、チェックボックスを
		// ON で開くために要る。**UI 起点の要求を Hub 側で埋めないのと対になっている**:
		// 埋めるのは画面で、人がそこから変えた段はそのまま送られる（子 plan:
		// docs/local/plan_derived-session-launch_c2_permission-tiers.md 内部 C6）。
		// 記憶が無ければ空のオブジェクト。
		"role_permission": rolePermissionMemory(cfg),
	})

writeJSON(w, providerListResponse{
		Revision:    registry.Revision(),
		Providers:   providerSummariesWithIcons(registry),
		Diagnostics: append(registry.Diagnostics(), providerCommandDiagnostics(registry)...),
	})

writeJSON(w, map[string]any{
		"provider_id":      id,
		"revision":         revision,
		"current_revision": current.Revision,
		"diff":             provider.DiffDistribution([]provider.Definition{current.Payload}, []provider.Definition{selected.Payload}, nil),
	})

writeJSON(w, map[string]any{
		"ok":   true,
		"diff": provider.DiffDistribution(current, candidate.Payload.Definitions, overrides),
	})

writeJSON(w, map[string]any{
		"lan_ip":      lanIP,
		"ssh_user":    sshUser,
		"ssh_port":    sshPort,
		"hub_port":    port,
		"ssh_command": sshCommand,
		"ssh_url":     sshURL,
		// hub_url は後方互換のため維持（= SSH 経路で開く 127.0.0.1 URL）。
		"hub_url":         sshForwardURL,
		"ssh_forward_url": sshForwardURL,
		"host_candidates": hostCandidates,

		// SSH 経路: OpenSSH Server 状態（C3 が有効化導線の出し分けに使う）。
		"sshd_state":     sshd.State,
		"sshd_installed": sshd.installed(),
		"sshd_running":   sshd.running(),

		// WireGuard（上級・接続後）の URL 雛形＋注記（ダミー撤廃）。
		"wireguard": map[string]any{
			"url_template":       wgURLTemplate,
			"url_template_https": wgURLTemplateHTTPS,
			"note":               "WireGuard サーバ IP は接続後にユーザーが指定する前提（Hub は WG 設定を持たない）。生IP は secure context 外のため通知/音声/PWA が制限される。HTTPS 化を推奨。",
		},
	})

SetCookie(w, &http.Cookie{
		Name:     tokenCookieName,
		Value:    "",
		Path:     "/",
		HttpOnly: true,
		Secure:   requestUsesHTTPS(r),
		// 発行側（handleIndex）と同じ Lax にそろえる。削除の一致判定は name/domain/path
		// だけなので機能上はどちらでも消えるが、属性が食い違っていると読む側が
		// 「token cookie は Strict」と誤読する。
		SameSite: http.SameSiteLaxMode,
		MaxAge:   -1, // -1 → Max-Age=0 を送出しブラウザは即削除
	})

writeJSON(w, map[string]any{
		"ok":       true,
		"total":    total,
		"offset":   offset,
		"messages": messages[offset:end],
	})

writeJSON(w, map[string]any{
		"ok":             true,
		"session_files":  sessionsRemoved,
		"spawn_files":    spawnRemoved,
		"store_sessions": storeSessions,
	})

writeJSON(w, map[string]any{
		"providers":           subscription.List(cfg, dir),
		"root":                config.SubscriptionsRoot(dir),
		"credentials_deleted": credentialsDeleted,
	})

writeJSON(w, map[string]any{
		"ok":         true,
		"inject":     inject,
		"saved_path": savedPath,
		"filename":   header.Filename,
	})

writeJSON(w, filesListResp{
			Root:      filesRoot,
			Exists:    false,
			Truncated: false,
			Items:     []filesListItem{},
		})

writeJSON(w, filesSaveResp{
		OK:    true,
		Path:  pathClean,
		Size:  newInfo.Size(),
		Mtime: newInfo.ModTime(),
	})

writeJSON(w, gitCommitMessageResp{
		OK:      true,
		Subject: subject,
		Body:    body,
	})

writeJSON(w, serverProfilesResponse{
			OK:       true,
			Profiles: pf.Profiles,
			LastUsed: pf.LastUsed,
			Active:   s.serverConns.activeResponses(active),
		})

