wire_structs.go_declaration:
type claudeStatusLineInput struct {
	RateLimitsFieldPresent bool   `json:"-"`
	Version                string `json:"version"`
	Model                  struct {
		DisplayName string `json:"display_name"`
	} `json:"model"`
	OutputStyle struct {
		Name string `json:"name"`
	} `json:"output_style"`
	Vim struct {
		Mode string `json:"mode"`
	} `json:"vim"`
	Agent struct {
		Name string `json:"name"`
	} `json:"agent"`
	Workspace struct {
		Repo struct {
			Host  string `json:"host"`
			Owner string `json:"owner"`
			Name  string `json:"name"`
		} `json:"repo"`
	} `json:"workspace"`
	Cost struct {
		TotalCostUSD       float64 `json:"total_cost_usd"`
		TotalDurationMs    float64 `json:"total_duration_ms"`
		TotalAPIDurationMs float64 `json:"total_api_duration_ms"`
		TotalLinesAdded    int     `json:"total_lines_added"`
		TotalLinesRemoved  int     `json:"total_lines_removed"`
	} `json:"cost"`
	ContextWindow struct {
		TotalInputTokens  int `json:"total_input_tokens"`
		TotalOutputTokens int `json:"total_output_tokens"`
		ContextWindowSize int `json:"context_window_size"`
		// UsedPercentage: Claude Code が実窓(200k/1M)を判定済みで算出した
		// context 使用率%（input 系トークンのみ。初回API応答前・/compact 直後は null→0）。
		UsedPercentage      float64 `json:"used_percentage"`
		RemainingPercentage float64 `json:"remaining_percentage"`
		CurrentUsage        struct {
			CacheCreationInputTokens int `json:"cache_creation_input_tokens"`
			CacheReadInputTokens     int `json:"cache_read_input_tokens"`
		} `json:"current_usage"`
	} `json:"context_window"`
	// Exceeds200kTokens: 直近 API 応答の総トークン（input+cache+output）が 200k 超か。
	// 実窓に依らない固定しきい値（1M 窓でも 200k 超で true）。
	Exceeds200kTokens bool `json:"exceeds_200k_tokens"`
	Effort            struct {
		Level string `json:"level"` // low/medium/high/xhigh/max。未対応モデルでは欠落。
	} `json:"effort"`
	Thinking struct {
		Enabled bool `json:"enabled"`
	} `json:"thinking"`
	// RateLimits: Claude.ai Pro/Max のみ・初回 API 応答後に出現。各窓は独立に欠落しうる。
	RateLimits *claudeRateLimits `json:"rate_limits"`
}

type claudeRateLimitWindow struct {
	UsedPercentage float64 `json:"used_percentage"`
	ResetsAt       int64   `json:"resets_at"`
}

type claudeRateLimits struct {
	FiveHour             *claudeRateLimitWindow `json:"five_hour"`
	SevenDay             *claudeRateLimitWindow `json:"seven_day"`
	FiveHourFieldPresent bool                   `json:"-"`
	SevenDayFieldPresent bool                   `json:"-"`
}

type codexStopInput struct {
	TranscriptPath string `json:"transcript_path"`
	// Model: フックが model を直接渡す場合
	Model string `json:"model"`
}

