	// トランスクリプトへの書き込みが同時ではないため（実測は同じ秒だが順序の保証は無い）。
	agentChatKickDelay = 80 * time.Millisecond
)

const (
	// 画面の回答（approval_consumed）・one-tap・自動承認・一括承認。Hub を経由した回答。
	approvalCloseAnswered = "answered"
	// 端末での回答。確定したユーザーターン（ブラウザの端末・入力欄・パネルの選択肢送信・
	// Hub からの送信）と、トランスクリプトに現れた user メッセージ。
	approvalCloseAnsweredTerminal = "answered_terminal"
	// 新しい候補に置き換わった。
	approvalCloseSuperseded = "superseded"
	// ネイティブの承認が画面から消えた（nativeApprovalClearMissLimit 回続けて検出されない）。
	// トランスクリプトの文章の質問の後に AI が答えを待たずに話し続けたときも、これで閉じる
	// （approval_text_question.go の「出力が落ち着いてから開く」節）。
	approvalCloseVanished = "vanished"
	// セッションが終わった（wrapper の切断・dismiss）。
	approvalCloseSessionEnd = "session_end"
	// 利用者が history reset を実行した。
	approvalCloseHistoryReset = "history_reset"
)

const (
	// cliVersionOutputCap bounds the combined stdout+stderr text kept per
	// provider. Past it, output is silently discarded rather than dropping the
	// run — many CLIs also print update banners or telemetry notices before
	// the version line, and the first line is what version_line uses anyway.
	cliVersionOutputCap = 8 * 1024
	// cliVersionMaxConcurrency bounds how many provider CLIs run at once so a
	// user with many custom providers configured cannot fork a burst of
	// processes in one click.
	cliVersionMaxConcurrency = 8
)

const (
	filesMaxDepth   = 8
	filesMaxItems   = 2000
