)

const (
	// 1 ファイル diff の上限。超えたら "\n(truncated)" を末尾に付与。
	gitShowDiffMaxBytes = 256 * 1024
	// メタ取得の pretty format。subject と body は \x1f (US) で分離する。
	// %H \t %P \t %an \t %ae \t %aI \t %D \t %s \x1f %b
