	// 含む行は数百 KB になり得るため bufio.Scanner の既定 64KB では足りない。
	grokHistoryLineMax = 8 * 1024 * 1024
	// grokHistoryMatchWindow は「セッション開始時刻 と Grok セッション作成時刻の
