	pinMaxDigits = 32
	// pinCookieName はリモート PIN 認証セッション cookie 名。
	pinCookieName = "MANY_AI_CLI_pin"
	// pinCookieTTL は PIN 認証セッションの有効期間。
	pinCookieTTL = 12 * time.Hour
