	//（分散ブルートフォース対策）。
	pinGlobalFailCap = 30
	// pinAttemptTTL は失敗カウント・既知デバイスの保持時間。
	pinAttemptTTL = time.Hour
)

const (
	// maxKnownDevices は既知デバイス map のソフト上限（TTL prune と併用）。
	maxKnownDevices = 256
