	knownDeviceTTL = 24 * time.Hour
)

const (
	pushStoreFilename = "push_store.json"
	pushSendTimeout   = 10 * time.Second
	// pushPerSubTimeout は購読 1 件あたりの Web Push 送信タイムアウト。
	// pushSendTimeout（親コンテキストの全体上限）を購読リスト全体で共有すると、
