const (
	idleAfter              = 3 * time.Second
	tickerInterval         = 200 * time.Millisecond
	maxPTYBuf              = proto.PTYReplayBufferLimit
	replayTailForNonActive = 64 * 1024 // 64 KB: 非アクティブセッションの UI 接続時 replay 上限
