const (
	// claudeSubagentParentReadBytesMax/RecordsMax bound the tail scan of the
	// *parent's* transcript used to resolve completion signals for every
	// child in one poll. Mirrors workflow_task_detail.go's
	// workflowTaskDetailReadBytesMax/RecordsMax (same shape of problem: find a
	// handful of marker records without reading a transcript that can reach
	// tens of MB). This is independent of subagentReadBudget's HeadBytes/
	// TailBytes, which bound the *child* jsonl reads instead (子 plan C2 完了条件
	// "10MB の合成 jsonl で...先頭 64KB と末尾 128KB を超えない" is about the child
	// file specifically).
	claudeSubagentParentReadBytesMax   = 2 * 1024 * 1024
	claudeSubagentParentReadRecordsMax = 500

	// claudeSubagentSummaryMax matches web/src/app/workflow-modal.ts'
	// clampForLine's default so LastToolSummary reads the same on both sides.
	claudeSubagentSummaryMax = 100

	claudeSubagentWorkflowAgentType = "workflow-subagent"

	// claudeSubagentFreshnessWindow is how recently a child's own jsonl must
	// have been modified, with zero parent-side launch/completion evidence
	// ever seen for it, to still be reported "running" instead of "unknown"
	// (C7 新しい規則). Same length as web/src/app/longproc.ts's STALL_SEC=600.
	claudeSubagentFreshnessWindow = 10 * time.Minute
)

const (
	// codexSubagentSessionMetaLineMax bounds a single rollout's first-line
	// read during discovery (子 plan C3 完了条件「子の探索で読むのは各
	// rollout の先頭行だけ」— this is that read, bounded the same way
	// agent_log_handler.go's readCodexSessionMeta already bounds its own
	// first-line-only read of the exact same file shape).
	codexSubagentSessionMetaLineMax = 4 * 1024 * 1024

	// codexSubagentParentReadBytesMax/RecordsMax bound the tail scan of the
	// *parent's* rollout used to resolve SubAgentActivity completion signals
	// for every child in one poll — independent of subagentReadBudget's
	// HeadBytes/TailBytes, which bound the *child* rollout reads instead
	// (mirrors claudeSubagentParentReadBytesMax/RecordsMax's same split).
	codexSubagentParentReadBytesMax   = 2 * 1024 * 1024
	codexSubagentParentReadRecordsMax = 500

	// codexSubagentMaxDayDirs bounds how many sessions/YYYY/MM/DD day
	// directories one poll's discovery walk will ever consider (from the
	// parent's own start date through today), so an unusually long-running
	// session cannot force an unbounded directory walk.
	codexSubagentMaxDayDirs = 32

	// codexSubagentUnseenSignalWindow bounds the "起動も完了も一度も見てい
	// ない子" fallback (親 plan「修正の C の共通の決まり」, 修正 C8): matches
	// web/src/app/longproc.ts's STALL_SEC = 600 — the same "still recent
	// enough to call it running without a direct SubAgentActivity signal"
	// window. Used only the first time a child is ever observed and never
	// re-evaluated afterward (see codexSubagentChildCache.FirstObservationDecided).
	codexSubagentUnseenSignalWindow = 10 * time.Minute
)

const (
	// grokSubagentParentReadBytesMax/RecordsMax bound the tail scan of the
	// *parent's* updates.jsonl used to resolve subagent_spawned/
	// subagent_finished signals for every still-in-flight child in one poll.
	// Mirrors claudeSubagentParentReadBytesMax/RecordsMax and
	// codexSubagentParentReadBytesMax/RecordsMax's identical role. Independent
	// of subagentReadBudget's HeadBytes/TailBytes, which bound each child's
	// own sibling events.jsonl tail read instead.
	grokSubagentParentReadBytesMax   = 2 * 1024 * 1024
	grokSubagentParentReadRecordsMax = 500
)

